test('fires immediately on first call', () => {
  vi.useFakeTimers();
  const fn = vi.fn();
  const t = throttle(fn, 200);
  t();
  expect(fn).toHaveBeenCalledTimes(1);
  vi.useRealTimers();
});

test('ignores calls within limit window', () => {
  vi.useFakeTimers();
  const fn = vi.fn();
  const t = throttle(fn, 200);
  t(); t(); t();
  expect(fn).toHaveBeenCalledTimes(1);
  vi.useRealTimers();
});

test('fires again after limit window passes', () => {
  vi.useFakeTimers();
  const fn = vi.fn();
  const t = throttle(fn, 200);
  t();
  vi.advanceTimersByTime(200);
  t();
  expect(fn).toHaveBeenCalledTimes(2);
  vi.useRealTimers();
});

